SourceCode.Declaration:
/// <summary>
/// CB202_SalesQuotaMinMax
/// SA line search class 1st inventory dimension specific otherwise inventDimIdBlank()
/// </summary>
internal final class METAgreementLineSearch
{
    ItemId                  itemId;
    SalesReceiptDate        receiptDate;
    CustAccount             custAccount;
    InventDim               inventDim;
    SalesUnit               salesUnit;
    SalesAgreementHeader    salesAgreementHeader;
    AgreementLine           agreementLine;
    AgreementClassification agreementClassification;

}

Method.Source:
/// <summary>
/// Get the SA header retrieved from the search
/// </summary>
/// <returns><c>SalesAgreementHeader</c> record; otherwise, null.</returns>
SalesAgreementHeader getSalesAgreementHeader()
{
    return salesAgreementHeader;
}

/// <summary>
/// Get the SA line retrieved from the search
/// </summary>
/// <returns><c>AgreementLine</c> record; otherwise, null.</returns>
AgreementLine getAgreementLine()
{
    return agreementLine;
}

/// <summary>
/// Get the SA classification retrieved from the search
/// </summary>
/// <returns><c>AgreementClassification</c> record; otherwise, null.</returns>
AgreementClassification getAgreementClassification()
{
    return agreementClassification;
}

/// <summary>
/// Construct
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <param name = "_receiptDate">Receipt date</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">SO line UOM</param>
/// <param name = "_inventDim">Sales order line inventory dimension</param>
/// <returns>Instance of class <c>METAgreementLineSearch</c></returns>
static METAgreementLineSearch construct(ItemId              _itemId,
                                        SalesReceiptDate    _receiptDate,
                                        CustAccount         _custAccount,
                                        SalesUnit           _salesUnit,
                                        InventDim           _inventDim)
{
    if (!_itemId || !_receiptDate || !_custAccount || !_salesUnit || !_inventDim)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METAgreementLineSearch(_itemId, _receiptDate, _custAccount, _salesUnit, _inventDim);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <param name = "_receiptDate">Receipt date</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">SO line UOM</param>
/// <param name = "_inventDim">Sales order line inventory dimension</param>
protected void new(ItemId           _itemId,
                   SalesReceiptDate _receiptDate,
                   CustAccount      _custAccount,
                   SalesUnit        _salesUnit,
                   InventDim        _inventDim)
{
    itemId      = _itemId;
    receiptDate = _receiptDate;
    custAccount = _custAccount;
    salesUnit   = _salesUnit;
    inventDim   = _inventDim;
}

/// <summary>
/// Run the SA line search
/// </summary>
/// <returns>True if SA line found; otherwise, false.</returns>
boolean run()
{        
    // had to split into 2 queries as the filter for UOM is only possible when AgreementLine is AgreementLineQuantityCommitment

    // Search for ProductQuantity
    if (this.findCommitmentType(CommitmentType::ProductQuantity))
    {
        return true;
    }        

    // search for ProductVolume
    return this.findCommitmentType(CommitmentType::ProductVolume);
}

/// <summary>
/// Find SA line by commitment type
/// </summary>
/// <param name = "_commitmentType">Commitment type quantity or volume</param>
/// <returns>True if SA line found; otherwise, false.</returns>
private boolean findCommitmentType(CommitmentType _commitmentType)
{
    boolean found = false;
    QueryRun qr;

    // Search SA line with SO line inventory dimension
    qr = new QueryRun(this.buildQuery(_commitmentType, inventDim));

    while (qr.next())
    {
        agreementLine = qr.get(tableNum(AgreementLine));
        salesAgreementHeader = qr.get(tableNum(SalesAgreementHeader));
        agreementClassification = qr.get(tableNum(AgreementClassification));
        return true;
    }

    // Search SA line with blank inventory dimension
    qr = new QueryRun(this.buildQuery(_commitmentType));

    while (qr.next())
    {
        agreementLine = qr.get(tableNum(AgreementLine));
        salesAgreementHeader = qr.get(tableNum(SalesAgreementHeader));
        agreementClassification = qr.get(tableNum(AgreementClassification));
        return true;
    }

    return found;
}

/// <summary>
/// Build the query to find the SA line
/// </summary>
/// <param name = "_commitmentType">Commitment type</param>
/// <param name = "_inventDim">SO line inventory dimension</param>
/// <returns><c>Query</c> object</returns>
private Query buildQuery(CommitmentType _commitmentType, InventDim _inventDim = null)
{
    QueryBuildRange qbr;
    Query query = new Query();
    QueryBuildDataSource agreementLineQbds, salesAgreementHeaderQbds, agreementClassificationQbds, inventDimQbds;        

    agreementLineQbds = query.addDataSource(tableNum(AgreementLine));
    agreementLineQbds.addRange(fieldNum(AgreementLine, ItemId)).value(queryValue(itemId));

    if (_commitmentType == CommitmentType::ProductQuantity)
    {
        agreementLineQbds.addRange(fieldNum(AgreementLineQuantityCommitment, ProductUnitOfMeasure)).value(queryValue(salesUnit));
    }

    agreementLineQbds.addRange(fieldNum(AgreementLine, EffectiveDate)).value(SysQueryRangeUtil::metLessThanEqualDate(receiptDate));
    agreementLineQbds.addRange(fieldNum(AgreementLine, ExpirationDate)).value(SysQueryRangeUtil::metGreaterThanEqualDate(receiptDate));

    salesAgreementHeaderQbds = agreementLineQbds.addDataSource(tableNum(SalesAgreementHeader));
    salesAgreementHeaderQbds.relations(true);
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, AgreementState)).value(queryValue(AgreementState::Effective));
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, CustAccount)).value(queryValue(custAccount));
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, DefaultAgreementLineType)).value(queryValue(_commitmentType));

    agreementClassificationQbds = salesAgreementHeaderQbds.addDataSource(tableNum(AgreementClassification));
    agreementClassificationQbds.relations(true);

    if (_inventDim)
    {            
        const str inventDimIdRange = '(%1.INVENTDIMID == %2.INVENTDIMID)';
        inventDimQbds = agreementClassificationQbds.addDataSource(tableNum(InventDim));
        inventDimQbds.joinMode(JoinMode::ExistsJoin);
        qbr = inventDimQbds.addRange(fieldNum(InventDim, InventDimId));
        qbr.value(strFmt(inventDimIdRange, inventDimQbds.name(), agreementLineQbds.name()));
        inventDimQbds.addRange(fieldNum(InventDim, InventSiteId)).value(queryValue(_inventDim.InventSiteId));
        inventDimQbds.addRange(fieldNum(InventDim, InventLocationId)).value(queryValue(_inventDim.InventLocationId));
    }
    else
    {
        agreementLineQbds.addRange(fieldNum(AgreementLine, InventDimId)).value(queryValue(InventDim::inventDimIdBlank()));
    }

    return query;
}
